  /**
   * @method
   * @name coincheck#fetchTradingFees
   * @description fetch the trading fees for multiple markets
   * @see https://coincheck.com/documents/exchange/api#account-info
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [fee structures]{@link
   * https://docs.ccxt.com/?id=fee-structure} indexed by market symbols
   */
  std::shared_future<ccxt::any>
  fetchTradingFees(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any response =
                     awaitValue(this->privateGetAccounts(params));
                 //
                 //     {
                 //         "success": true,
                 //         "id": "7487995",
                 //         "email": "some@email.com",
                 //         "identity_status": "identity_pending",
                 //         "bitcoin_address": null,
                 //         "lending_leverage": "4",
                 //         "taker_fee": "0.0",
                 //         "maker_fee": "0.0",
                 //         "exchange_fees": {
                 //           "btc_jpy": { taker_fee: '0.0', maker_fee: "0.0" },
                 //           "etc_jpy": { taker_fee: '0.0', maker_fee: "0.0" },
                 //           "fct_jpy": { taker_fee: '0.0', maker_fee: "0.0" },
                 //           "mona_jpy": { taker_fee: '0.0', maker_fee: "0.0"
                 //           }, "plt_jpy": { taker_fee: '0.0', maker_fee: "0.0"
                 //           }
                 //         }
                 //     }
                 //
                 ccxt::any fees = this->safeValue(
                     response, std::string("exchange_fees"), ccxt::dict{});
                 ccxt::any result = ccxt::dict{};
                 ccxt::any symbols = this->symbols;
                 if (isTrue(isEqual(symbols, ccxt::any{}))) {
                   return result;
                 }
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(symbols));
                      postFixIncrement(i)) {
                   ccxt::any symbol = ::getValue(symbols, i);
                   ccxt::any market = this->market(symbol);
                   ccxt::any fee = this->safeValue(
                       fees, ::getValue(market, std::string("id")),
                       ccxt::dict{});
                   ::setValue(
                       result, symbol,
                       ccxt::dict{
                           {std::string("info"), fee},
                           {std::string("symbol"), symbol},
                           {std::string("maker"),
                            this->safeNumber(fee, std::string("maker_fee"))},
                           {std::string("taker"),
                            this->safeNumber(fee, std::string("taker_fee"))},
                           {std::string("percentage"), true},
                           {std::string("tierBased"), false},
                       });
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name coincheck#createOrder
   * @description create a trade order
   * @see https://coincheck.com/documents/exchange/api#order-new
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  createOrder(ccxt::any symbol, ccxt::any type, ccxt::any side,
              ccxt::any amount, ccxt::any price = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("pair"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(isEqual(type, std::string("market")))) {
                   ::setValue(request, std::string("order_type"),
                              add(add(type, std::string("_")), side));
                   if (isTrue(isEqual(side, std::string("sell")))) {
                     ::setValue(request, std::string("amount"), amount);
                   } else {
                     ccxt::any cost =
                         this->safeNumber(params, std::string("cost"));
                     params = this->omit(params, std::string("cost"));
                     if (isTrue(!isEqual(cost, ccxt::any{}))) {
                       throw ArgumentsRequired(toString(
                           add(this->id,
                               std::string(
                                   " createOrder() : you should use \"cost\" "
                                   "parameter instead of \"amount\" argument "
                                   "to create market buy orders"))));
                     }
                     ::setValue(request, std::string("market_buy_amount"),
                                cost);
                   }
                 } else {
                   ::setValue(request, std::string("order_type"), side);
                   ::setValue(request, std::string("rate"), price);
                   ::setValue(request, std::string("amount"), amount);
                 }
                 ccxt::any response =
                     awaitValue(this->privatePostExchangeOrders(
                         this->extend(request, params)));
                 ccxt::any id = this->safeString(response, std::string("id"));
                 return this->safeOrder(
                     ccxt::dict{
                         {std::string("id"), id},
                         {std::string("info"), response},
                     },
                     market);
               })
        .share();
  }

