  virtual ccxt::any parseTransactionStatus(ccxt::any status) {
    ccxt::any statuses = ccxt::dict{
        {std::string("pending"), std::string("pending")},
        {std::string("processing"), std::string("pending")},
        {std::string("finished"), std::string("ok")},
        {std::string("canceled"), std::string("canceled")},
        {std::string("confirmed"), std::string("pending")},
        {std::string("received"), std::string("ok")},
    };
    return this->safeString(statuses, status, status);
  }

  ccxt::any parseTransaction(ccxt::any transaction,
                             ccxt::any currency = ccxt::any{},
                             ccxt::any p2 = ccxt::any{},
                             ccxt::any p3 = ccxt::any{}) override {
    //
    // fetchDeposits
    //
    // {
    //       "id": 2,
    //       "amount": "0.05",
    //       "currency": "BTC",
    //       "address": "13PhzoK8me3u5nHzzFD85qT9RqEWR9M4Ty",
    //       "status": "confirmed",
    //       "confirmed_at": "2015-06-13T08:29:18.000Z",
    //       "created_at": "2015-06-13T08:22:18.000Z"
    //  }
    //
    // fetchWithdrawals
    //
    //  {
    //       "id": 398,
    //       "status": "finished",
    //       "amount": "242742.0",
    //       "currency": "JPY",
    //       "created_at": "2014-12-04T15:00:00.000Z",
    //       "bank_account_id": 243,
    //       "fee": "400.0",
    //       "is_fast": true
    //  }
    //
    ccxt::any id = this->safeString(transaction, std::string("id"));
    ccxt::any timestamp = this->parse8601(
        this->safeString(transaction, std::string("created_at")));
    ccxt::any address = this->safeString(transaction, std::string("address"));
    ccxt::any amount = this->safeNumber(transaction, std::string("amount"));
    ccxt::any currencyId =
        this->safeString(transaction, std::string("currency"));
    ccxt::any code = this->safeCurrencyCode(currencyId, currency);
    ccxt::any status = this->parseTransactionStatus(
        this->safeString(transaction, std::string("status")));
    ccxt::any updated = this->parse8601(
        this->safeString(transaction, std::string("confirmed_at")));
    ccxt::any fee = ccxt::any{};
    ccxt::any feeCost = this->safeNumber(transaction, std::string("fee"));
    if (isTrue(!isEqual(feeCost, ccxt::any{}))) {
      fee = ccxt::dict{
          {std::string("cost"), feeCost},
          {std::string("currency"), code},
      };
    }
    return ccxt::dict{
        {std::string("info"), transaction},
        {std::string("id"), id},
        {std::string("txid"), ccxt::any{}},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("network"), ccxt::any{}},
        {std::string("address"), address},
        {std::string("addressTo"), address},
        {std::string("addressFrom"), ccxt::any{}},
        {std::string("tag"), ccxt::any{}},
        {std::string("tagTo"), ccxt::any{}},
        {std::string("tagFrom"), ccxt::any{}},
        {std::string("type"), ccxt::any{}},
        {std::string("amount"), amount},
        {std::string("currency"), code},
        {std::string("status"), status},
        {std::string("updated"), updated},
        {std::string("comment"), ccxt::any{}},
        {std::string("internal"), ccxt::any{}},
        {std::string("fee"), fee},
    };
  }

  ccxt::any nonce() override { return this->milliseconds(); }

  ccxt::any sign(ccxt::any path, ccxt::any api = std::string("public"),
                 ccxt::any method = std::string("GET"),
                 ccxt::any params = ccxt::dict{},
                 ccxt::any headers = ccxt::any{},
                 ccxt::any body = ccxt::any{}) override {
    ccxt::any url =
        add(add(::getValue(::getValue(this->urls, std::string("api")),
                           std::string("rest")),
                std::string("/")),
            this->implodeParams(path, params));
    ccxt::any query = this->omit(params, this->extractParams(path));
    if (isTrue(isEqual(api, std::string("public")))) {
      if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(query)), 0))) {
        url = add(url, add(std::string("?"), this->urlencode(query)));
      }
    } else {
      this->checkRequiredCredentials();
      ccxt::any nonce = toString(this->nonce());
      ccxt::any queryString = std::string("");
      if (isTrue(isEqual(method, std::string("GET")))) {
        if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(query)), 0))) {
          url = add(url, add(std::string("?"),
                             this->urlencode(this->keysort(query))));
        }
      } else {
        if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(query)), 0))) {
          body = this->urlencode(this->keysort(query));
          queryString = body;
        }
      }
      ccxt::any auth = add(add(nonce, url), queryString);
      headers = ccxt::dict{
          {std::string("Content-Type"),
           std::string("application/x-www-form-urlencoded")},
          {std::string("ACCESS-KEY"), this->apiKey},
          {std::string("ACCESS-NONCE"), nonce},
          {std::string("ACCESS-SIGNATURE"),
           this->hmac(this->encode(auth), this->encode(this->secret), sha256)},
      };
    }
    return ccxt::dict{
        {std::string("url"), url},
        {std::string("method"), method},
        {std::string("body"), body},
        {std::string("headers"), headers},
    };
  }

  ccxt::any handleErrors(ccxt::any httpCode, ccxt::any reason, ccxt::any url,
                         ccxt::any method, ccxt::any headers, ccxt::any body,
                         ccxt::any response, ccxt::any requestHeaders,
                         ccxt::any requestBody) override {
    if (isTrue(isEqual(response, ccxt::any{}))) {
      return ccxt::any{};
    }
    //
    //     {"success":false,"error":"disabled API Key"}'
    //     {"success":false,"error":"invalid authentication"}
    //
    ccxt::any success = this->safeBool(response, std::string("success"), true);
    if (isTrue(!isEqual(success, true))) {
      ccxt::any error = this->safeString(response, std::string("error"));
      ccxt::any feedback =
          add(add(this->id, std::string(" ")), this->json(response));
      this->throwExactlyMatchedException(
          ::getValue(this->exceptions, std::string("exact")), error, feedback);
      this->throwBroadlyMatchedException(
          ::getValue(this->exceptions, std::string("broad")), body, feedback);
      throw ExchangeError(
          toString(add(add(this->id, std::string(" ")), this->json(response))));
    }
    return ccxt::any{};
  }
